// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.annotation.Annotation;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

import org.eclipse.kura.internal.rest.configuration.ConfigurationRestService;
import org.eclipse.kura.internal.rest.auth.SessionRestService;
import org.eclipse.kura.internal.rest.identity.provider.IdentityRestServiceV1;
import org.eclipse.kura.internal.rest.identity.provider.IdentityRestServiceV2;
import org.eclipse.kura.internal.rest.security.provider.SecurityRestServiceV1;
import org.eclipse.kura.internal.rest.security.provider.SecurityRestServiceV2;
import org.eclipse.kura.internal.rest.service.listing.provider.RestServiceListingProvider;
import org.eclipse.kura.rest.system.SystemRestService;
import org.junit.Test;

import com.fasterxml.jackson.databind.JsonNode;

import io.swagger.v3.core.util.Json;
import io.swagger.v3.core.util.Yaml;
import jakarta.ws.rs.HttpMethod;

public class GenerateOpenApiTest {

    private Path output;
    private JsonNode document;
    private JsonNode yaml;

    @Test
    public void generatedFormatsDescribeTheSameApi() throws Exception {
        givenBuildOutput();

        whenDocumentsAreRead();

        thenFormatsAreEquivalent();
        thenMetadataDescribesTheApi();
        thenReferencesResolve(this.document);
        thenOperationsMatchResources();
    }

    private void givenBuildOutput() {
        this.output = Path.of(System.getProperty("openapi.directory"));
    }

    private void whenDocumentsAreRead() throws Exception {
        this.document = Json.mapper().readTree(Files.readString(this.output.resolve("openapi.json")));
        this.yaml = Yaml.mapper().readTree(Files.readString(this.output.resolve("openapi.yaml")));
    }

    private void thenFormatsAreEquivalent() {
        assertEquals(this.document, this.yaml);
    }

    private void thenMetadataDescribesTheApi() {
        assertEquals("3.0.3", this.document.path("openapi").asText());
        assertEquals("/services", this.document.at("/servers/0/url").asText());
        assertFalse(this.document.at("/info/version").asText().isEmpty());
        assertFalse(this.document.at("/info/version").asText().contains("${"));
    }

    private void thenReferencesResolve(JsonNode node) {
        if (node.has("$ref")) {
            final String reference = node.get("$ref").asText();
            assertTrue(reference, reference.startsWith("#/"));
            assertFalse(reference, this.document.at(reference.substring(1)).isMissingNode());
        }
        node.forEach(this::thenReferencesResolve);
    }

    private void thenOperationsMatchResources() {
        final Set<String> expected = new HashSet<>();
        for (Class<?> resource : Set.of(SystemRestService.class, ConfigurationRestService.class, SessionRestService.class,
                IdentityRestServiceV1.class, IdentityRestServiceV2.class, SecurityRestServiceV1.class,
                SecurityRestServiceV2.class, RestServiceListingProvider.class)) {
            final String base = resource.getAnnotation(jakarta.ws.rs.Path.class).value();
            for (Method method : resource.getMethods()) {
                for (Annotation annotation : method.getAnnotations()) {
                    final HttpMethod verb = annotation.annotationType().getAnnotation(HttpMethod.class);
                    if (verb != null) {
                        final jakarta.ws.rs.Path suffix = method.getAnnotation(jakarta.ws.rs.Path.class);
                        final String path = ("/" + base + "/" + (suffix == null ? "" : suffix.value())).replaceAll("/+", "/");
                        expected.add(verb.value().toLowerCase(Locale.ROOT) + " " + path);
                    }
                }
            }
        }
        final Set<String> actual = new HashSet<>();
        final Set<String> identifiers = new HashSet<>();
        this.document.path("paths").fields().forEachRemaining(path -> path.getValue().fields().forEachRemaining(operation -> {
            actual.add(operation.getKey() + " " + path.getKey());
            final String identifier = operation.getValue().path("operationId").asText();
            assertFalse(identifier.isEmpty());
            assertTrue("Duplicate operationId: " + identifier, identifiers.add(identifier));
        }));
        assertEquals(expected, actual);
    }
}
